spec.rawSql:
SELECT takeoff_local AS "Take-off (local)", printf('%d min %02d s', duration_s::INTEGER // 60, duration_s::INTEGER % 60) AS "Duration", distance_m AS "Distance", energy_wh AS "Energy",
       wh_per_km AS "Energy per km", max_height_m AS "Highest", wind_ms AS "Mean wind"
FROM $flights WHERE flight = ${flight:raw}
